  orgId: OrgId,
  patch: Partial<
    Pick<
      OrganizationUsage,
110→      "seatsUsed" | "projectsUsed" | "issuesUsed" | "storageMbUsed"
    >
  >,
): Promise<OrganizationUsage> {
  const current = await getUsage(orgId);

  const row = getDb()
