import type { IsoTimestamp, OrgId, ProjectId, UserId } from "./common";
import type { IssuePriority } from "./issue";

/** How often a chore rule files an issue. */
export type RecurrenceCadence = "daily" | "weekly";

/**
 * A rule the recurring-issue job turns into an ordinary issue.
 *
 * `startsOn`, `lastOccurrenceOn` and filed occurrence days are calendar dates
 * (`YYYY-MM-DD`) in `timezone`. `weekday` is the ISO weekday, 1 = Monday …
 * 7 = Sunday, and is set only for weekly rules.
 */
export interface RecurringIssue {
  readonly id: string;
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly title: string;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
  readonly lastOccurrenceOn: string | null;
  readonly paused: boolean;
  readonly createdBy: UserId;
  readonly createdAt: IsoTimestamp;
  readonly updatedAt: IsoTimestamp;
}

import { z } from "zod";
import {
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { issuePrioritySchema } from "./issue";

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** True for a real Gregorian `YYYY-MM-DD` date, so `2026-02-30` is rejected. */
function isCalendarDate(value: string): boolean {
  const match = CALENDAR_DATE.exec(value);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (month < 1 || month > 12) return false;

  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const daysInMonth = [0, 31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= (daysInMonth[month] ?? 0);
}

/** True when `timeZone` is an IANA zone this runtime can format with. */
function isKnownTimeZone(timeZone: string): boolean {
  if (timeZone.length === 0) return false;
  try {
    Intl.DateTimeFormat("en-US", { timeZone }).format(0);
    return true;
  } catch {
    return false;
  }
}

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3).max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z.string(),
    startsOn: z.string(),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "A weekly rule needs a weekday from 1 (Monday) to 7 (Sunday).",
      });
    }

    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "A daily rule must not set a weekday.",
      });
    }

    if (!isKnownTimeZone(value.timezone)) {
      ctx.addIssue({
        code: "custom",
        path: ["timezone"],
        message: "Timezone must be an IANA time zone the runtime knows.",
      });
    }

    if (!isCalendarDate(value.startsOn)) {
      ctx.addIssue({
        code: "custom",
        path: ["startsOn"],
        message: "startsOn must be a real YYYY-MM-DD calendar date.",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<typeof createRecurringIssueSchema>;

import { index, integer, sqliteTable, text } from "drizzle-orm/sqlite-core";
import { idColumn, tenantColumns, timestampColumns } from "./_shared";

export const recurringIssues = sqliteTable(
  "recurring_issues",
  {
    id: idColumn(),
    ...tenantColumns,
    projectId: text("project_id").notNull(),
    title: text("title").notNull(),
    priority: text("priority", {
      enum: ["none", "low", "medium", "high", "urgent"],
    })
      .notNull()
      .default("none"),
    assigneeId: text("assignee_id"),
    cadence: text("cadence", { enum: ["daily", "weekly"] }).notNull(),
    /** ISO weekday 1 = Monday … 7 = Sunday. Null for daily rules. */
    weekday: integer("weekday"),
    timezone: text("timezone").notNull(),
    startsOn: text("starts_on").notNull(),
    lastOccurrenceOn: text("last_occurrence_on"),
    paused: integer("paused", { mode: "boolean" }).notNull().default(false),
    createdBy: text("created_by").notNull(),
    ...timestampColumns,
  },
  (table) => [
    index("recurring_issues_org_created_idx").on(table.orgId, table.createdAt),
    index("recurring_issues_paused_idx").on(table.paused),
  ],
);

export type RecurringIssueRow = typeof recurringIssues.$inferSelect;
export type NewRecurringIssueRow = typeof recurringIssues.$inferInsert;

/**
 * Recurring-issue rules. Request paths are org-scoped; the background job
 * reads every non-paused rule across organizations, the same way the webhook
 * delivery claim is cross-tenant on purpose.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type { z } from "zod";
import type { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import type { IsoTimestamp, OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type { RecurrenceCadence, RecurringIssue } from "@/types/recurring-issue";

type ParsedCreate = z.output<typeof createRecurringIssueSchema>;

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    projectId: row.projectId as ProjectId,
    title: row.title,
    priority: row.priority as IssuePriority,
    assigneeId: row.assigneeId === null ? null : (row.assigneeId as UserId),
    cadence: row.cadence as RecurrenceCadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: row.createdBy as UserId,
    createdAt: row.createdAt as IsoTimestamp,
    updatedAt: row.updatedAt as IsoTimestamp,
  };
}

export async function insertRecurringIssue(
  input: ParsedCreate,
  createdBy: UserId,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toRecurringIssue(row);
}

export async function findRecurringIssueById(
  orgId: OrgId,
  id: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .get();
  return row ? toRecurringIssue(row) : null;
}

/** Creation order: earlier `created_at`, then SQLite rowid for same-millisecond ties. */
export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(asc(recurringIssues.createdAt), asc(sql`rowid`))
    .all();
  return rows.map(toRecurringIssue);
}

/** Every stored rule counts toward the plan cap, paused ones included. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

/** Cross-tenant work list for the recurring-issue job. */
export async function listUnpausedRecurringIssues(): Promise<readonly RecurringIssue[]> {
  const rows = getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(asc(recurringIssues.createdAt), asc(sql`rowid`))
    .all();
  return rows.map(toRecurringIssue);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  id: string,
  paused: boolean,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ paused, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function setLastOccurrenceOn(
  orgId: OrgId,
  id: string,
  lastOccurrenceOn: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .update(recurringIssues)
    .set({ lastOccurrenceOn, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(recurringIssues.orgId, orgId), eq(recurringIssues.id, id)))
    .returning()
    .get();
  return row ? toRecurringIssue(row) : null;
}

/**
 * Recurring-issue rules: who may create or pause one, and the plan cap on how
 * many an organization may keep.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { orgResource, projectResource, requireFound } from "./_support";
import type { CreateRecurringIssueInput } from "@/schemas/recurring-issue";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

/**
 * Stores a chore rule. Invalid input throws `ZodError` before anything is
 * written. The rule starts unpaused and with no occurrence filed yet.
 */
export async function createRecurringIssue(
  actor: Actor,
  input: CreateRecurringIssueInput,
): Promise<RecurringIssue> {
  const parsed = createRecurringIssueSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(parsed.orgId, parsed.projectId),
    "Project",
    parsed.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  if (parsed.assigneeId !== null) {
    const assignee = await memberRepo.findMember(parsed.orgId, parsed.assigneeId);
    if (assignee === null || assignee.status !== "active") {
      throw new Error(
        `Assignee ${parsed.assigneeId} is not an active member of the organization`,
      );
    }
  }

  const org = requireFound(
    await orgRepo.findOrgById(parsed.orgId),
    "Organization",
    parsed.orgId,
  );
  const used = await recurringRepo.countRecurringIssues(parsed.orgId);
  if (wouldExceedLimit(org.plan, "recurringIssues", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more recurring issues`,
    );
  }

  return recurringRepo.insertRecurringIssue(parsed, actor.userId);
}

/** Pause or resume one rule. Same permission as creating an issue in its project. */
export async function setRecurringIssuePaused(
  actor: Actor,
  input: { orgId: OrgId; recurringIssueId: string; paused: boolean },
): Promise<RecurringIssue> {
  assertOrgScope(actor, input.orgId);

  const rule = requireFound(
    await recurringRepo.findRecurringIssueById(input.orgId, input.recurringIssueId),
    "RecurringIssue",
    input.recurringIssueId,
  );
  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, rule.projectId),
    "Project",
    rule.projectId,
  );
  assertCan(actor, "issue:create", projectResource(project));

  if (rule.paused === input.paused) return rule;

  return requireFound(
    await recurringRepo.setRecurringIssuePaused(input.orgId, rule.id, input.paused),
    "RecurringIssue",
    rule.id,
  );
}

/** Rules of the actor's organization, oldest first. */
export async function listRecurringIssues(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "issue:read", orgResource(orgId));
  return recurringRepo.listRecurringIssues(orgId);
}

/**
 * Files at most one issue per non-paused recurring rule: the latest occurrence
 * whose local calendar day has started by `now`. Missed days are not back-filled.
 */
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError, can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { CreateIssueInput } from "@/schemas/issue";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Calendar date of `instant` in `timeZone`, as `YYYY-MM-DD`. */
function localCalendarDate(instant: Date, timeZone: string): string {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  const map: Record<string, string> = {};
  for (const part of fmt.formatToParts(instant)) {
    if (part.type !== "literal") map[part.type] = part.value;
  }
  const year = (map.year ?? "").padStart(4, "0");
  const month = (map.month ?? "").padStart(2, "0");
  const day = (map.day ?? "").padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Moves a Gregorian date by whole calendar days, independent of timezone. */
function shiftCalendarDate(ymd: string, deltaDays: number): string {
  const match = CALENDAR_DATE.exec(ymd);
  if (!match) {
    throw new Error(`Invalid calendar date: ${ymd}`);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCDate(date.getUTCDate() + deltaDays);
  const y = String(date.getUTCFullYear()).padStart(4, "0");
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
function isoWeekday(ymd: string): number {
  const match = CALENDAR_DATE.exec(ymd);
  if (!match) return 0;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  const js = date.getUTCDay();
  return js === 0 ? 7 : js;
}

/**
 * Latest occurrence day that has started by `now`.
 *
 * A day D has started once local time in the rule's zone has reached 00:00 on
 * D, which is exactly when `localCalendarDate(now)` is D or later. Daily rules
 * occur every day on or after `startsOn`; weekly rules only on `weekday`.
 */
function latestStartedOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  if (rule.weekday === null) return null;

  for (let ago = 0; ago < 7; ago += 1) {
    const candidate = shiftCalendarDate(today, -ago);
    if (candidate < rule.startsOn) return null;
    if (isoWeekday(candidate) === rule.weekday) return candidate;
  }

  return null;
}

/**
 * Files L for one rule, or leaves it alone. Returns true only when an issue
 * was created. A refusal from issue creation (quota, and anything else that
 * is not "the creator can no longer file") does not pause the rule and does
 * not advance `lastOccurrenceOn`.
 */
async function fileOccurrence(rule: RecurringIssue, now: Date): Promise<boolean> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return false;
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return false;
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null || isArchived(project)) return false;

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  const actor: Actor | null =
    creator !== null && creator.status === "active"
      ? { userId: creator.userId, orgId: creator.orgId, role: creator.role }
      : null;

  if (actor === null || !can(actor, "issue:create", {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  })) {
    await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    return false;
  }

  let assigneeId = rule.assigneeId;
  if (assigneeId !== null) {
    const assignee = await memberRepo.findMember(rule.orgId, assigneeId);
    if (assignee === null || assignee.status !== "active") assigneeId = null;
  }

  const input: CreateIssueInput = {
    orgId: rule.orgId,
    projectId: rule.projectId,
    title: `${rule.title} (${occurrence})`,
    description: null,
    status: "backlog",
    priority: rule.priority,
    assigneeId,
    parentId: null,
    estimate: null,
    dueAt: null,
    labelIds: [],
  };

  try {
    await createIssue(actor, input);
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      await recurringRepo.setRecurringIssuePaused(rule.orgId, rule.id, true);
    }
    return false;
  }

  await recurringRepo.setLastOccurrenceOn(rule.orgId, rule.id, occurrence);
  return true;
}

/** `processed` counts issues created. One rule's failure does not stop the rest. */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringRepo.listUnpausedRecurringIssues();

    for (const rule of rules) {
      try {
        const created = await fileOccurrence(rule, now);
        if (created) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("recurring issue rule failed", {
          id: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

