{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"/**
 * Files at most one issue per non-paused recurring rule: the latest occurrence
 * whose local calendar day has started by `now`. Missed days are not back-filled.
 */
import { createLogger } from "@/lib/logger";
import { PermissionDeniedError, can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { CreateIssueInput } from "@/schemas/issue";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";

const logger = createLogger("recurring-issue-job");

const CALENDAR_DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

/** Calendar date of `instant` in `timeZone`, as `YYYY-MM-DD`. */
function localCalendarDate(instant: Date, timeZone: string): string {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  const map: Record<string, string> = {};
  for (const part of fmt.formatToParts(instant)) {
    if (part.type !== "literal") map[part.type] = part.value;
  }
  const year = (map.year ?? "").padStart(4, "0");
  const month = (map.month ?? "").padStart(2, "0");
  const day = (map.day ?? "").padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Moves a Gregorian date by whole calendar days, independent of timezone. */
function shiftCalendarDate(ymd: string, deltaDays: number): string {
  const match = CALENDAR_DATE.exec(ymd);
  if (!match) {
    throw new Error(`Invalid calendar date: ${ymd}`);
  }
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCDate(date.getUTCDate() + deltaDays);
  const y = String(date.getUTCFullYear()).padStart(4, "0");
  const m = String(date.getUTCMonth() + 1).padStart(2, "0");
  const d = String(date.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${d}`;
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
function isoWeekday(ymd: string): number {
  const match = CALENDAR_DATE.exec(ymd);
  if (!match) return 0;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  date.setUTCHours(0, 0, 0, 0);
  const js = date.getUTCDay();
  return js === 0 ? 7 : js;
}

/**
 * Latest occurrence day that has started by `now`.
 *
 * A day D has started once local time in the rule's zone has reached 00:00 on
 * D, which is exactly when `localCalendarDate(now)` is D or later. Daily rules
 * occur every day on or after `startsOn`; weekly rules only on `weekday`.
 */
function latestStartedOccurrence(rule: RecurringIssue, now: Date): string | null {
  const today = localCalendarDate(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  if (rule.weekday === null) return null;

  for (let ago = 0; ago < 7; ago += 1) {
