import { eq } from "drizzle-orm";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { ZodError } from "zod";
import { newId } from "@/lib/id";
import { PermissionDeniedError } from "@/lib/permissions";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { getDb, issues, members } from "@/server/db";
import { enqueue, drain, resetQueue } from "@/server/jobs/queue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { subscribe } from "@/lib/event-bus";
import { toIsoTimestamp } from "@/types/common";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OrgId, UserId } from "@/types/common";

let cleanup: () => void;
let growth: Tenant;
let starter: Tenant;
let free: Tenant;
let enterprise: Tenant;

const ORG = "01HZZZAAAAAAAAAAAAAAAAAAAA" as OrgId;
const PROJECT = "01HZZZCCCCCCCCCCCCCCCCCCCC" as ProjectIdPlaceholder;
type ProjectIdPlaceholder = OrgId;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  growth = await createTenant("growth", "growth");
  starter = await createTenant("starter", "starter");
  free = await createTenant("free", "free");
  enterprise = await createTenant("enterprise", "enterprise");
});

afterAll(() => {
  cleanup();
});

function base(tenant: Tenant, overrides: Record<string, unknown> = {}) {
  return {
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    title: "Daily triage",
    cadence: "daily" as const,
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...overrides,
  };
}

describe("schema", () => {
  it("accepts a daily rule and defaults priority, assignee and weekday", () => {
    const parsed = createRecurringIssueSchema.parse({
      orgId: ORG,
      projectId: PROJECT,
      title: "Daily triage",
      cadence: "daily",
      timezone: "UTC",
      startsOn: "2026-03-05",
    });
    expect(parsed.priority).toBe("none");
    expect(parsed.assigneeId).toBeNull();
    expect(parsed.weekday).toBeNull();
  });

  it("rejects impossible dates, bad zones and cadence/weekday mismatches", () => {
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Daily triage",
        cadence: "daily",
        timezone: "UTC",
        startsOn: "2026-02-30",
      }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Daily triage",
        cadence: "daily",
        timezone: "UTC",
        startsOn: "2026-02-29",
      }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Daily triage",
        cadence: "daily",
        timezone: "UTC",
        startsOn: "2024-02-29",
      }).success,
    ).toBe(true);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Daily triage",
        cadence: "daily",
        timezone: "Not/AZone",
        startsOn: "2026-03-01",
      }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Weekly",
        cadence: "weekly",
        timezone: "America/New_York",
        startsOn: "2026-03-01",
      }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Daily",
        cadence: "daily",
        weekday: 1,
        timezone: "UTC",
        startsOn: "2026-03-01",
      }).success,
    ).toBe(false);
    expect(
      createRecurringIssueSchema.safeParse({
        orgId: ORG,
        projectId: PROJECT,
        title: "Weekly",
        cadence: "weekly",
        weekday: 1,
        timezone: "America/New_York",
        startsOn: "2026-03-02",
      }).success,
    ).toBe(true);
  });
});

describe("service", () => {
  it("rejects invalid input with ZodError and stores nothing", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...base(growth),
        startsOn: "2026-02-30",
      }),
    ).rejects.toBeInstanceOf(ZodError);
    const listed = await recurringIssueService.listRecurringIssues(
      growth.actors.member,
      growth.org.id,
    );
    expect(listed).toEqual([]);
  });

  it("enforces tenant scope, project, archive, permission, assignee and quota", async () => {
    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, base(starter)),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...base(growth),
        projectId: starter.project.id,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    await projectRepo.archiveProject(growth.org.id, growth.project.id);
    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, base(growth)),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
    await projectRepo.restoreProject(growth.org.id, growth.project.id);

    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.viewer, base(growth)),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...base(growth),
        assigneeId: newId() as UserId,
      }),
    ).rejects.toThrow();

    const suspended = await memberRepo.findMember(growth.org.id, growth.userIds.admin);
    if (!suspended) throw new Error("missing admin");
    await getDb()
      .update(members)
      .set({ status: "suspended" })
      .where(eq(members.id, suspended.id))
      .run();
    await expect(
      recurringIssueService.createRecurringIssue(growth.actors.member, {
        ...base(growth),
        assigneeId: growth.userIds.admin,
      }),
    ).rejects.toThrow();
    await getDb()
      .update(members)
      .set({ status: "active" })
      .where(eq(members.id, suspended.id))
      .run();

    await expect(
      recurringIssueService.createRecurringIssue(free.actors.member, base(free)),
    ).rejects.toThrow();
    expect(
      await recurringIssueService.listRecurringIssues(free.actors.owner, free.org.id),
    ).toEqual([]);

    const made = [];
    for (let i = 0; i < 3; i += 1) {
      made.push(
        await recurringIssueService.createRecurringIssue(starter.actors.member, {
          ...base(starter),
          title: `Starter chore ${i + 1}`,
        }),
      );
    }
    expect(made[0]?.paused).toBe(false);
    expect(made[0]?.lastOccurrenceOn).toBeNull();
    expect(made[0]?.createdBy).toBe(starter.userIds.member);
    await expect(
      recurringIssueService.createRecurringIssue(starter.actors.member, {
        ...base(starter),
        title: "Starter chore 4",
      }),
    ).rejects.toThrow();
    const starterRules = await recurringIssueService.listRecurringIssues(
      starter.actors.viewer,
      starter.org.id,
    );
    expect(starterRules.map((rule) => rule.title)).toEqual([
      "Starter chore 1",
      "Starter chore 2",
      "Starter chore 3",
    ]);

    await expect(
      recurringIssueService.setRecurringIssuePaused(starter.actors.viewer, {
        orgId: starter.org.id,
        recurringIssueId: made[0]!.id,
        paused: true,
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    const paused = await recurringIssueService.setRecurringIssuePaused(
      starter.actors.member,
      { orgId: starter.org.id, recurringIssueId: made[0]!.id, paused: true },
    );
    expect(paused.paused).toBe(true);

    await expect(
      recurringIssueService.setRecurringIssuePaused(starter.actors.member, {
        orgId: growth.org.id,
        recurringIssueId: made[0]!.id,
        paused: false,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    await expect(
      recurringIssueService.setRecurringIssuePaused(starter.actors.member, {
        orgId: starter.org.id,
        recurringIssueId: "missing",
        paused: true,
      }),
    ).rejects.toBeInstanceOf(NotFoundError);

    for (let i = 0; i < 4; i += 1) {
      await recurringIssueService.createRecurringIssue(enterprise.actors.owner, {
        ...base(enterprise),
        title: `Enterprise chore ${i + 1}`,
      });
    }
  });
});

describe("job", () => {
  it("files the latest occurrence once, honors timezone, archive, role and quota", async () => {
    const rule = await recurringIssueService.createRecurringIssue(growth.actors.member, {
      ...base(growth),
      title: "Daily triage",
      priority: "high",
